summary:
Тесты камеры зелёные (40 из 40, включая 8 новых). Теперь перевожу `Game.ts` на `CameraDirector`.

```json
{"version":1,"taskId":"dd88a27d-b0e9-4d56-b808-2a9da5c6d446","commandId":"patch-game-1","operation":"run","headSha":"e0a720a0b8185824d35e09937c677a9ed3d5752e","timeoutSeconds":600,"command":"cat > /tmp/patch-game.cjs <<'EOF'
const fs = require('fs');
const file = 'src/game/Game.ts';
let src = fs.readFileSync(file, 'utf8');

const oldUpdateCamera = `  private updateCamera(dt: number): void {
    if (this.match.phase === 'simulating' || this.match.phase === 'hole-intro') {
      const focus = this.ballPosition();
      this.cameraController.setTarget({ x: focus.x, y: focus.y + 0.35, z: focus.z });
    }
    this.cameraController.update(dt, this.cameraView());
    if (this.options.input.wasPressed('camera-reset')) this.focusCamera(this.ballPosition());
    const pose = this.cameraController.state;
    const camera = this.options.camera;
    camera.position.set(pose.position.x, pose.position.y, pose.position.z);
    camera.lookAt(pose.target.x, pose.target.y, pose.target.z);
  }`;

const newUpdateCamera = `  /** The director owns the reset key, the mode machine and the damping; feed it the ball. */
  private updateCamera(dt: number): void {
    this.cameraDirector.setFocus(this.ballPosition());
    applyCameraPose(this.options.camera, this.cameraDirector.update(dt, this.cameraView()));
  }`;

const oldFocusCamera = `  private focusCamera(position: Vec3): void {
    const dx = this.hole.cup.position.x - position.x;
    const dz = this.hole.cup.position.z - position.z;
    const yaw = Math.abs(dx) + Math.abs(dz) < 1e-5 ? Math.PI : Math.atan2(-dx, -dz);
    this.cameraController.reset({ x: position.x, y: position.y + 0.35, z: position.z });
    this.cameraController.setOrbit(yaw, CAMERA_PITCH, CAMERA_DISTANCE);
  }`;

const newFocusCamera = `  /** Slides the camera behind the ball facing the cup; the pose is never cut. */
  private focusCamera(position: Vec3): void {
    this.cameraDirector.focusOn(position);
  }`;

const edits = [
  [
    `import { CameraController } from '../camera/CameraController';`,
    `import { CameraDirector } from '../camera/CameraDirector';\nimport { applyCameraPose } from '../camera/ThreeCameraBinding';`,
  ],
  [
    `  private readonly cameraController = new CameraController({ pitch: CAMERA_PITCH, distance: CAMERA_DISTANCE });`,
    `  private readonly cameraDirector = new CameraDirector({\n    modes: { aim: { pitch: CAMERA_PITCH, distance: CAMERA_DISTANCE } },\n  });`,
  ],
  [
    `    this.focusCamera(hole.spawn);`,
    `    this.cameraDirector.setFraming({ bounds: hole.bounds, spawn: hole.spawn, cup: hole.cup.position });\n    this.cameraDirector.setFocus(hole.spawn);\n    this.cameraDirector.setMode('overview', { force: true, immediate: first });`,
  ],
  [`this.cameraController.state.yaw`, `this.cameraDirector.yaw`],
  [
    `    this.statusText = undefined;\n    this.aimArrow.visible = false;\n  }\n\n  private finishTurn`,
    `    this.statusText = undefined;\n    this.aimArrow.visible = false;\n    this.cameraDirector.setMode('follow');\n  }\n\n  private finishTurn`,
  ],
  [oldUpdateCamera, newUpdateCamera],
  [oldFocusCamera, newFocusCamera],
];

for (const [from, to] of edits) {
  if (!src.includes(from)) throw new Error('anchor not found: ' + from.slice(0, 70));
  src = src.replace(from, to);
}

fs.writeFileSync(file, src);
console.log('Game.ts patched');
